insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-library-check-per-version-key-s687','decision','A Library accessibility check covers one version key','SkyPipit (S687), #3572: a check record names one key (draft:<id>, version:<v> or page). The latest check for the page''s current key decides the Public gate; a draft''s check never carries over to the page it becomes. cpl_library_set_public() refuses a listing without that pass; service_role is exempt.',array['library','s687'],'proposed','docs/reference/lanes/library.md; #3572','SkyPipit (S687)',null,'SkyPipit (S687)',date '2026-11-19'),
('d-library-new-page-unlists-s687','decision','A listed piece whose page changes leaves the Public Library until it passes','SkyPipit (S687), COBIx on #3572: when a listed piece''s version or url changes, a trigger unlists it unless the new page key has a passing check, and keeps publish_target public so Part 2''s run relists it. Until then this overrides Sam''s Nov 19 item 9 (a Public piece stays listed while redrafted); his to reverse.',array['library','s687'],'proposed','docs/reference/lanes/library.md; #3572','SkyPipit (S687)',null,'SkyPipit (S687)',date '2026-11-19'),
('d-library-internal-one-press-s687','decision','Publish to Internal Library approves and starts the publish run in one press','SkyPipit (S687), #3572: Publish to Internal Library approves a new piece and dispatches library-publish.yml at once, honoring the two-minute hold. The Edge Function accepts a reviewer only, so a team-phrase press waits for the scheduled run every three hours.',array['library','s687'],'proposed','docs/reference/lanes/library.md; #3572','SkyPipit (S687)',null,'SkyPipit (S687)',date '2026-11-19'),
('d-library-3560-in-four-prs-s687','decision','Issue #3560 is built in four PRs, one after another','SkyPipit (S687): #3560''s asks share library.js, so they land in order: 1 the two publish buttons, Template, check and settings tables and the gate (#3572); 2 the publish run''s accessibility check, the footer from the check record, listing on a pass; 3 the progress bar from real steps; 4 Publish all, Add existing, redraft and republish.',array['library','s687'],'proposed','docs/reference/lanes/library.md; #3572','SkyPipit (S687)',null,'SkyPipit (S687)',date '2026-11-19')
on conflict (slug) do nothing;

